it('missing DISCORD_CLIENT_ID is detected by validateRequiredEnvVars', () => {
    const result = validateRequiredEnvVars({ ...BASE_ENV, DISCORD_CLIENT_ID: undefined });
    expect(result.ok).toBe(false);
    if (!result.ok) {
      expect(result.missingVars).toContain('DISCORD_CLIENT_ID');
    }
  });
